const $ = s => document.querySelector(s);
const esc = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state, screen='home', stack=[];
function resetDemo(){state={goal:$('#goal').value,reason:'time',minutes:35,note:'',applied:null,finished:false,partial:false,feedback:null,preference:null,remember:false,previewUsed:false};stack=[];go('home',false);}
function changeGoal(goal){state.goal=goal;state.applied=null;state.feedback=null;state.finished=false;state.partial=false;stack=[];go('home',false);}
const action=(text,js,style='primary',disabled=false)=>`<button class="${style}" onclick="${js}" ${disabled?'disabled':''}>${text}</button>`;
const nav=(text,to,style='link')=>action(text,`go('${to}')`,style);
const card=html=>`<div class="card pad">${html}</div>`;
const option=(title,description,js,active=false)=>`<button class="option ${active?'active':''}" onclick="${js}"><span><b>${title}</b>${description?`<small>${description}</small>`:''}</span><span class="arrow" aria-hidden="true">›</span></button>`;
const sessionCount=()=>state.applied?.reason==='time'&&state.applied.minutes===25?2:6;
const completedCount=partial=>`${partial?(sessionCount()===2?1:4):sessionCount()} of ${sessionCount()} exercises`;
const priority=()=>state.goal==='strength'?'Improve your bench press':'Build your shoulders';
function go(to,push=true){if(push&&to!==screen)stack.push(screen);screen=to;render();}
function back(){screen=stack.pop()||'home';render();}
function choose(reason,swap='lateral'){state.reason=reason;state.swap=swap;state.remember=false;state.guide=null;go(reason==='pain'?'pain':reason==='unsure'?'guide':reason==='other'?'context':reason==='equipment'?(state.previewUsed&&!state.applied?'pro':'review'):'time');}
function review(){go(state.reason==='time'&&state.minutes===45?'review':state.previewUsed&&!state.applied?'pro':'review');}
function apply(){state.applied={reason:state.reason,goal:state.goal,minutes:state.minutes,swap:state.swap};state.previewUsed=true;if(state.remember&&state.reason==='time')state.preference=state.minutes;go('workout');announce('Adjustment applied to today’s workout.');}
function undo(){state.applied=null;go('workout');announce('Original workout restored.');}
function finish(partial){state.finished=true;state.partial=partial;go('saved');}
function feedback(value){state.feedback=value;go(value==='no'?'feedbackDetail':'outcome');}
function announce(message){$('#announcement').textContent=message;}
function scenario(to){stack=[];if(to==='saved'){state.finished=true;state.partial=false;state.applied=null;}if(to==='feedback'){state.applied={reason:'time',minutes:35,goal:state.goal};state.finished=true;state.partial=false;}go(to,false);}
function render(){let h='',f='',title='',body='',points=[];
$('#nav').innerHTML=[['home','Weekly plan'],['workout','Adjust today'],['saved','Normal completion'],['feedback','After an adjustment'],['preferences','Training preferences']].map(([id,label])=>`<button aria-current="${screen===id}" onclick="scenario('${id}')">${label}</button>`).join('');
$('.back').style.visibility=screen==='home'?'hidden':'visible';
if(screen==='home'){
h=`<h2>Your weekly workout plan</h2><hr class="rule"><p>▦ Week 3 · Sep 21–27</p><p class="eyeline">Your focus</p><div class="goal">${priority()}</div>${nav('Track weekly progress','progress')}`;
if(state.applied&&!state.finished)h+=card(`<div class="row"><h3>Ready for today</h3><span class="badge">Adjusted</span></div><p>${state.applied.reason==='time'?'A shorter session, with your priority work kept.':'An alternative using the equipment available.'}</p>${nav('View today’s workout','workout')}`);
if(state.preference&&!state.applied)h+=card(`<h3>Tuesday preference</h3><p>You usually have ${state.preference} minutes. Review today’s plan before changing it.</p>${action('Review a shorter version',`state.minutes=state.preference;choose('time')`,'link')}`);
h+=`<div class="card"><div class="head"><div class="row"><b>Tuesday</b><span>${state.finished?(state.partial?'Finished early':'Completed'):'Today'}</span></div><div>Upper body</div></div><div class="pad"><p>${state.finished?(completedCount(state.partial)+' completed'):`${sessionCount()} exercises · Dumbbells, barbell, machine`}</p>${nav(state.finished?'View saved workout':'View workout','workout')}</div></div><div class="card pad"><h3>Thursday</h3><p>Lower body</p><span class="pill">45 min planned</span></div>${nav('Training preferences','preferences')}`;
f=nav(state.finished?'View saved workout':'Start today’s workout','workout','primary');title='The workout remains the main event';body='No permanent coaching banner. Show contextual help only when an adjustment or confirmed preference makes it useful.';points=['Scenario controls outside the phone let you explore independent moments. They are not steps users must complete.','The goal selector demonstrates how the recommendation changes.','Existing day cards, top bar, spacing and primary action remain familiar.'];
}
if(screen==='workout'){
h=`<p class="eyeline">Tuesday · Upper body</p><h2>${state.finished?'Your saved workout':'Today’s workout'}</h2><p class="goal">${priority()}</p>${state.finished?`<div class="banner">${(state.partial?'Finished early · ':'Completed · ')+completedCount(state.partial)}</div>`:''}`;
if(state.applied)h+=`<div class="banner"><b>Adjusted for today</b><p class="compact">${state.applied.reason==='time'?(state.applied.minutes===25?'A reduced two-exercise session today.':'Your priority work stays. Less direct arm work today.'):(state.applied.swap==='bench'?'Barbell bench press replaced with dumbbells.':'Cable lateral raise replaced with dumbbells.')}</p>${!state.finished?action('Undo adjustment','undo()','link'):''}</div>`;
if(!state.finished)h+=option('Adjust today','Less time, different equipment, or help with an exercise.',`go('reasons')`);
h+=`<div class="card"><div class="head"><b>${state.goal==='strength'?(state.applied?.swap==='bench'?'1. Dumbbell bench press':'1. Barbell bench press'):'1. '+(state.applied?.reason==='equipment'?'Dumbbell':'Cable')+' lateral raise'}</b></div><div class="pad"><p class="muted">${state.goal==='strength'?'Your strength focus':'Your shoulder focus'}</p><table class="sets"><thead><tr><th>Set</th><th>Target</th><th>Status</th></tr></thead><tbody>${[1,2,3].map(i=>`<tr><td>${i}</td><td>${state.goal==='strength'?'6–8 reps':'10–12 reps'}</td><td>${state.finished?'Logged':'Planned'}</td></tr>`).join('')}</tbody></table>${action('How to perform',`state.guide='${state.goal==='strength'?'Bench press':'Lateral raise'}';go('guide')`,'link')}${!state.finished?'<hr class="rule">'+action('Need an alternative?',`choose('equipment','${state.goal==='strength'?'bench':'lateral'}')`,'link'):''}</div></div><p class="muted">${state.applied?.reason==='time'&&state.applied.minutes===25?(state.goal==='strength'?'Also in today’s reduced plan: row.':'Also in today’s reduced plan: overhead press.'):`Also in your plan: row, overhead press, ${state.goal==='strength'?'lateral raise':'bench press'}, curl and triceps extension.`}</p>`;
f=state.finished?nav('Back to workout plan','home','primary'):nav('Finish workout','finish','primary')+nav('Finish early','early','link quiet');title='One clear place to ask for help';body='The routine is an illustrative excerpt. Production keeps existing load entry, rest timers, exercise controls and tutorials.';points=['All planned sets are initially unlogged in this sample. Completion routes simulate recorded results.','Adjustment rules must freeze already performed work. Undo cannot delete logged sets.','A finished session is distinct from completing all prescribed work.'];
}
if(screen==='reasons'){
h=`<p class="eyeline">Today’s upper-body workout</p><h2>What would help today?</h2><p class="muted">Choose one to get started.</p>${option('I have less time','Keep the most relevant work.',`choose('time')`)}${option('Equipment is unavailable','Find a suitable alternative.',`choose('equipment')`)}${option('Show me how','Understand an exercise before changing it.',`choose('unsure')`)}${option('Something hurts','Pause and decide what to do next.',`choose('pain')`)}${option('Something else','Tell Trainr in your own words.',`choose('other')`)}`;
f=nav('Keep today’s plan','workout','link quiet');title='Recognition before typing';body='Common needs go straight to a relevant action. No explanation is required for a simple request.';points=['Implement this compact chooser as an expanding sheet in Compose.','“Show me how” uses the existing tutorial instead of changing the plan.','Pain never goes through the routine substitution or Pro flow.'];
}
if(screen==='time'){
h=`<h2>How much time do you have?</h2><p class="muted">For the whole session, including warm-up and rest.</p><div class="choices">${[25,35,45].map(n=>action(n+' min',`state.minutes=${n};render()`,'choice'+(state.minutes===n?' active':''))).join('')}</div><p class="eyeline">Your priority</p><div class="goal">${priority()}</div><p>We’ll show what stays and what changes before you decide.</p><label class="toggle"><input type="checkbox" ${state.remember?'checked':''} onchange="state.remember=this.checked"><span>Remember this Tuesday time limit<br><span class="muted">Future workouts will still ask before changing.</span></span></label>`;
f=action('Show recommendation','review()')+nav('Keep today’s plan','workout','link quiet');title='One question, one decision';body='The remembered preference is opt-in. The proposed plan change is scoped to today.';points=['A production estimate must include warm-up, setup, rests and performed work.','This prototype uses authored examples for 25, 35 and 45 minutes; no inference is running.','If a safe, useful plan cannot fit, state that rather than compressing rest or promising equal results.'];
}
if(screen==='review'){
const equip=state.reason==='equipment',bench=state.swap==='bench',normal=!equip&&state.minutes===45,short=!equip&&state.minutes===25;
h=`<h2>${equip?'Use the dumbbells today':normal?'Keep your current workout':'A shorter workout for today'}</h2><p class="eyeline">Your priority</p><div class="goal">${priority()}</div>`;
if(normal){h+=`<p>Your planned session already fits the time you selected. There’s no need to change it.</p><div class="scope"><b>Original workout · 45 minutes planned</b></div>`;f=action('Continue workout',`if(state.remember)state.preference=state.minutes;go('workout')`);}
else{
if(!equip)h+=`<p class="muted">Your time today: ${state.minutes} minutes</p>`;
h+=`<div class="scope"><b>Today only</b><span class="muted">· Undo available</span></div>`;
h+=card(`<h3>${equip?'A suitable alternative':state.goal==='strength'?'Keep your bench work':'Keep your shoulder work'}</h3><p>${equip?(bench?'Barbell bench press → Dumbbell bench press':'Cable lateral raise → Dumbbell lateral raise'):state.goal==='strength'?'Keep bench press and rows. Shorten the remaining work.':'Keep lateral raises and overhead press. Shorten the remaining work.'}</p><div class="tradeoff"><b>Tradeoff</b><p>${equip?(bench?'Less practice with the barbell today. Dumbbell loads are tracked separately.':'The resistance feels different. Choose the load separately.'):short?'Less exercise variety and less total work today. This is a reduced session.':'Less direct arm work today.'}</p></div><details class="details"><summary>See exact changes</summary>${equip?`<div class="diff"><span>${bench?'Barbell bench press<br><b>Dumbbell bench press</b>':'Cable lateral raise<br><b>Dumbbell lateral raise</b>'}</span><span>${bench?'3 × 6–8':'3 × 10–12'}</span></div><p>Keep the planned rest. Select the starting weight separately.</p>`:short?`<div class="diff"><span>${state.goal==='strength'?'Bench press':'Lateral raise'}</span><span>Keep 3 sets</span></div><div class="diff"><span>${state.goal==='strength'?'Row':'Overhead press'}</span><span>Keep 3 sets</span></div><div class="diff"><span>Other 4 exercises</span><span>Omit today</span></div>`:'<div class="diff"><span>Dumbbell curl</span><span>3 → 2 sets</span></div><div class="diff"><span>Triceps extension</span><span>3 → 2 sets</span></div><p>Other exercises and planned rests stay the same.</p>'}</details>`);
if(equip)h+=`<details class="details"><summary>How to choose the weight</summary><p>Use a light practice set to find a weight you can control through the movement. Don’t transfer the previous exercise’s weight to the dumbbells.</p><p>Log this exercise separately so future targets use its own history.</p>${action('View exercise guidance',`state.guide='${bench?'Dumbbell bench press':'Dumbbell lateral raise'}';go('guide')`,'link')}</details>`;
h+=`<details class="details"><summary>Why this change?</summary><p>${equip?(bench?'Dumbbells let you train a pressing movement today, but they do not replace practice of your barbell bench press.':'It trains the shoulders using the dumbbells available to you. It is a different movement with its own load history.'):`This example prioritizes ${state.goal==='strength'?'your bench press':'your shoulder exercises'} within today’s time limit. A shorter session does not promise the same training effect.`}</p><p>Missed sets won’t be automatically added to your next workout.</p></details>`;
f=action('Use this workout','apply()')+nav('Keep original','workout','link quiet');}
title='Make the coaching decision legible';body='The first layer shows priority, change, tradeoff and scope. Exact programming and rationale are available on demand.';points=['These sample prescriptions require coach review and deterministic eligibility, load, volume and timing validation before production.','Do not assume compound exercises always outrank isolation exercises.','Only the selected obstacle is addressed. Equipment swaps do not also reduce sets.'];
}
if(screen==='early'||screen==='finish'){
const partial=screen==='early';h=`<h2>${partial?'Finish early?':'Save this workout?'}</h2>${card(`<h3>${partial?'Save only what you performed':'Your recorded workout'}</h3><p>${completedCount(partial)+' completed'}</p><p class="muted">${partial?'Unchecked sets stay unperformed. Your logged work is kept.':'Your recorded sets and weights will be kept.'}</p>`)}<p class="muted">${partial?'No need to make up the remaining sets right now.':'You can leave a note after saving, if you want.'}</p>`;f=action('Save workout',`finish(${partial})`)+nav('Keep training','workout','link quiet');title='Save before asking anything';body='Saving does not depend on the model, a subscription or feedback.';points=['Both screens simulate existing logged work. They do not infer performance from prescribed values.','The early-finish path must never call the existing complete-all function.','Completion counts and next-workout selection must understand a closed partial session.'];
}
if(screen==='saved'){
h=`<div class="success" aria-hidden="true">✓</div><h2 class="center">Workout saved</h2><p class="center muted">${state.partial?completedCount(true)+' · Finished early':'Your session is in your training history.'}</p>${card(`<h3>Anything to change next time?</h3><p class="muted">Optional. Your workout is already saved.</p>${nav('Leave a note','debrief')}`)}`;
if(state.applied)h+=nav('Tell us how the adjustment went','feedback');f=nav('Done','home','primary');title='A normal session ends in one tap';body='No forced survey and no automatic chat. “Done” returns to the weekly plan.';points=['Keep the existing completion celebration and progress link in production.','Offer a specific follow-up only after the relevant adjusted session.','No paywall on saving a workout, recording a concern or seeing your own history.'];
}
if(screen==='debrief'){
h=`<h2>Anything for next time?</h2><label class="label" for="note">Your note</label><textarea id="note" oninput="state.note=this.value;document.getElementById('saveNote').disabled=!this.value.trim()" placeholder="For example: I had to leave early for work.">${esc(state.note)}</textarea><p class="hint">Optional notes stay on this device.</p>`;f=`<button id="saveNote" class="primary" ${state.note.trim()?'':'disabled'} onclick="go('noteSaved')">Save note</button>`+nav('Skip','saved','link quiet');title='Notes do not silently rewrite plans';body='The completed session stays saved. A debrief is context for a future recommendation.';points=['Production can offer one relevant clarification after interpreting the note.','This prototype saves text without pretending to interpret arbitrary input.','A recurring constraint needs explicit confirmation.'];
}
if(screen==='noteSaved'){
h=`<h2>Note saved</h2><div class="summary">${esc(state.note)}</div><p>Your next workout has not changed.</p>${nav('View training preferences','preferences')}`;f=nav('Back to workout plan','home','primary');title='Separate memory from action';body='Saving a note never means agreeing to an adjustment.';points=['User-authored observations and model interpretations remain distinguishable.','A future recommendation should link back to this note as its source.'];
}
if(screen==='context'){
h=`<h2>Tell us what you need</h2><label class="label" for="context">What would make today work better?</label><textarea id="context" oninput="state.note=this.value" placeholder="Add any context you want Trainr to consider.">${esc(state.note)}</textarea><p class="hint">Private on this device.</p><p>Which part should we look at first?</p>${option('The time I have','Review a shorter version.',`choose('time')`)}${option('The equipment available','Review an alternative.',`choose('equipment')`)}`;f=nav('Back to workout','workout','link quiet');title='Clarify only what is missing';body='In production, the local model would identify the need and ask at most the necessary next question.';points=['This authored preview asks the user to choose rather than claiming to understand arbitrary text.','Model failure falls back to these controls, preserving the draft and logged session.'];
}
if(screen==='guide'){
h=`<h2>Understand the exercise</h2><p class="muted">${state.guide||'The exercise you are working on'}</p>${card('<h3>Use your existing demonstration</h3><p>Follow the setup and movement instructions in Trainr’s exercise tutorial.</p>')}<p>Check the equipment setup before starting. If you’re still unsure, ask a qualified trainer to demonstrate.</p><p class="muted">Your workout has not changed.</p>`;f=nav('Back to workout','workout','primary');title='Teach before substituting';body='This slot embeds Trainr’s real exercise-specific HowToSection and VideoTutorial in production.';points=['No fabricated demonstration or generic model-written technique cues.','A tutorial teaches movement; it does not verify the user’s actual form.'];
}
if(screen==='pain'){
h=`<h2>Pause this exercise</h2><p>Don’t push through pain to finish the plan.</p>${card('<h3>Get the right help</h3><p>Trainr cannot assess the cause of pain or choose a safe replacement from a message.</p><p>If pain is new, worsening or persistent, seek guidance from a qualified healthcare professional.</p>')}<p class="muted">You can save what you’ve done without completing the remaining sets.</p>`;f=nav('Save and finish early','early','primary')+nav('Return to workout','workout','link quiet');title='A separate, free path for pain';body='Pain is not treated as an equipment constraint. There is no automated substitution or upgrade prompt here.';points=['Production needs clinician-reviewed symptom escalation content, including urgent symptoms.','These short messages are illustrative product copy, not a diagnostic system.'];
}
if(screen==='feedback'){
h=`<p class="eyeline">Your workout is saved</p><h2>Did the adjustment help?</h2><p>${state.applied?.reason==='equipment'?'You used dumbbells instead of the cable machine.':'You tried a shorter version of your workout.'}</p>${option(state.applied?.reason==='equipment'?'Yes, it worked':'Yes, it fit my time','',`feedback('yes')`)}${option('Not quite','Tell us what still needs changing.',`feedback('no')`)}${option('Something was uncomfortable','Pause and get appropriate guidance.',`go('pain')`)}`;f=nav('Not now','home','link quiet');title='One relevant question';body='Measure practicality first. Do not translate “it fit” into a claim of strength or muscle gain.';points=['Show this once for the relevant session, not after every workout forever.','This scenario simulates a completed adjusted workout.','The next screen separates personal feedback from long-term results.'];
}
if(screen==='feedbackDetail'){
h=`<h2>What still needs changing?</h2>${option('It still took too long','Save this for the next review.',`state.feedback='Still too long';go('outcome')`)}${option('The exercise was confusing','Save feedback and open the guidance.',`state.feedback='Exercise was confusing';go('guide')`)}${option('Something else','Add a note without changing your plan.',`go('debrief')`)}`;f=nav('Save for later','home','link quiet');title='Follow up without overcorrecting';body='An unsuccessful adjustment calls for clarification, not automatic further cuts.';points=['No extra sets are moved to another day without review.','Keep future changes as proposals.'];
}
if(screen==='outcome'){
h=`<h2>Feedback saved</h2>${card(`<h3>How it fit</h3><p>${state.feedback==='yes'?'You said this version worked for you.':esc(state.feedback||'You asked for another look.')}</p>`)}<h3 class="section-title">Progress toward your goal</h3><p>We need more comparable sessions to assess your ${state.goal==='strength'?'strength':'training performance'} trend.</p><p class="muted">One useful adjustment does not tell us whether your long-term results have improved.</p><div class="scope"><b>Your future workouts have not changed.</b></div>`;f=nav('Done','home','primary');title='Practical success and training results are different';body='Separate the user’s experience from what the performance data can support.';points=['For muscle growth, performance is a supporting indicator, not a direct measurement of hypertrophy.','Do not compare kilograms across different exercises as equivalent.','No invented confidence score or improvement percentage.'];
}
if(screen==='preferences'){
h=`<h2>Your training preferences</h2><p class="muted">Things you have asked Trainr to remember.</p>${state.preference?card(`<h3>Tuesday time limit</h3><p>${state.preference} minutes for the whole session</p><p class="hint">Confirmed by you</p>${nav('Edit','editPreference')}${action('Forget',`state.preference=null;render();announce('Time preference forgotten')`,'link')}`):'<div class="summary">No saved preferences yet. You can remember a time limit when adjusting a workout.</div>'}${state.note?card(`<h3>Your session note</h3><p>${esc(state.note)}</p>${action('Delete note',`state.note='';render()`,'link')}`):''}<h3 class="section-title">Today’s adjustment</h3><p>${state.applied?(state.applied.reason==='time'?'Shorter session · Today only':'Equipment alternative · Today only'):'No adjustment applied.'}</p><p class="hint">Forgetting a preference stops future use. It does not remove past workouts.</p>`;f=nav('Back to workout plan','home','primary');title='Memory with ownership';body='A plain list of confirmed facts. Notes, preferences and applied changes remain separate.';points=['View, edit and forget remain available after Pro expires.','Forgetting does not undo a workout that has already been performed.','In production each item links to its source and confirmation date.'];
}
if(screen==='editPreference'){
h=`<h2>Tuesday time limit</h2><p class="muted">Time for the whole workout</p><div class="choices">${[25,35,45].map(n=>action(n+' min',`state.preference=${n};render()`,'choice'+(state.preference===n?' active':''))).join('')}</div><p>Changes apply to future recommendations. Today’s workout stays as it is.</p>`;f=nav('Done','preferences','primary');title='Edit the preference, not the historical record';body='The saved constraint is independent of any applied plan.';points=['This preference editor saves changes immediately.','Recheck weekday scope when workouts are rescheduled.'];
}
if(screen==='progress'){
h=`<h2>Your weekly progress</h2><p class="goal">${priority()}</p>${card(`<h3>Sessions logged</h3><p>${state.finished?'1 of 3':'0 of 3'} this week</p>${state.partial?'<p class="muted">Includes one session finished early.</p>':''}`)}<h3 class="section-title">Training trend</h3><p class="muted">Not enough comparable logged sessions in this example.</p><p>Completed sessions show participation. Your recorded sets and weights help assess performance.</p>`;f=nav('Back to workout plan','home','primary');title='Honest progress reporting';body='Participation and performance have separate meanings.';points=['Illustrative progress screen; do not replace the existing weekly history UI.','Track targets versus actual entries, including whether values were explicitly confirmed.'];
}
if(screen==='pro'){
h=`<span class="badge">Trainr Pro</span><h2>Keep adapting your training</h2><p>Your first adjustment is included. Pro adds ongoing recommendations and follow-ups tailored to your training.</p>${card('<h3>Your workout is still available</h3><p>You can keep training, log sets, save notes and finish early.</p>')}<p class="muted">Your current request will be kept while you review Pro.</p>`;f=action('Preview Pro continuation',`state.previewUsed=false;go('review')`)+nav('Keep original workout','workout','link quiet');title='A contextual upgrade, after demonstrated value';body='In production this continues into the existing RevenueCat paywall and resumes the saved request after purchase.';points=['The prototype button simulates a successful continuation. No price or transaction is connected.','Check device eligibility and model readiness before presenting a purchase.','The first adjustment’s follow-up remains included after its preview is used.'];
}
$('#screen').innerHTML=h;$('#footer').innerHTML=f;$('#noteTitle').textContent=title;$('#noteBody').textContent=body;$('#noteList').innerHTML=points.map(p=>`<li>${p}</li>`).join('');$('#screen').scrollTop=0;$('#screen').focus({preventScroll:true});
}
resetDemo();
